const inputs=$input.all(), prepared=$('Prepare Domain Search Batch').all(0,$runIndex);
const state=JSON.parse(JSON.stringify(prepared[0].json.state));
const priority=new Map(state.tlds.map((t,i)=>[t,i]));
const preferred=new Set(String(state.request['Selected Domains']||'').toLowerCase().split('\n').map(s=>s.trim()).filter(Boolean));
const lev=(a,b)=>{const m=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=m[0];m[0]=i;for(let j=1;j<=b.length;j++){const old=m[j];m[j]=Math.min(m[j]+1,m[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=old}}return m[b.length]};
const sim=(a,b)=>1-lev(a,b)/Math.max(a.length,b.length,1);
const map=new Map(), retry=[];
for(let index=0;index<inputs.length;index++) {
 const response=inputs[index].json, body=response.body??response;
 const status=Number(response.statusCode||200), error=body.error;
 if(status===429||error?.code==='RATE_LIMIT_EXCEEDED'||(error?.code==='DOMAIN_SEARCH_FAILED'&&/too many requests|rate limit/i.test(error?.message||''))) {
  const keyword=prepared[index]?.json.keyword;
  if(keyword&&(state.keywordRetries[keyword]||0)<3){state.keywordRetries[keyword]=(state.keywordRetries[keyword]||0)+1;retry.push(keyword)}
  continue;
 }
 if(status>=400||error)throw new Error('Domain availability request failed: '+String(error?.message||status));
 if(!Array.isArray(body.exact)&&!Array.isArray(body.suggestions))throw new Error('Unexpected domain availability response');
 const add=(d,tier)=>{if(d?.available!==true||!d.domain)return;const domain=String(d.domain).trim().toLowerCase(),tld=domain.split('.').pop(),root=domain.split('.')[0];if(!state.tlds.includes(tld)||!Number.isFinite(Number(d.price))||Number(d.price)<0||map.has(domain))return;map.set(domain,{domain,tld,price:Number(d.price),root,preferred:preferred.has(domain)?0:1,tier})};
 for(const d of body.exact||[])add(d,0);for(const d of body.suggestions||[])add(d,1);
}
const pool=[...map.values()].sort((a,b)=>a.preferred-b.preferred||a.tier-b.tier||(priority.get(a.tld)??99)-(priority.get(b.tld)??99)||a.price-b.price||a.domain.localeCompare(b.domain));
// Keep all domains accepted in earlier passes; only fill the missing slots.
for(const d of pool){if(state.domains.length>=state.count)break;if(state.domains.every(x=>sim(d.root,x.root)<=0.78))state.domains.push(d)}
state.pendingKeywords=[...new Set([...retry,...state.pendingKeywords])];
state.complete=state.domains.length>=state.count;
state.canSearchMore=!state.complete&&state.pendingKeywords.length>0&&state.searchRound<20;
state.reviewMessage=state.complete?'':`Found ${state.domains.length} of ${state.count} distinct available domains. Saved the partial list. Add more Suggested Domains or permitted TLDs and generate again.`;
state.quoteBody={cart:{domains:state.domains.map(d=>({domain:d.domain,tld:d.tld,mailboxes:{provider:state.provider,count:2}}))},promo_code:state.promo};
return [{json:state}];

const c=$('Build Next Batch').item.json;
if($json.error?.code==='DOMAINS_UNAVAILABLE'||String($json.error?.message||'').toLowerCase().includes('not available'))return [{json:{id:c.requestId,'Approve Purchase':false,Status:'Generate Domains','Next Batch At':null,'Automation Error':'Checkout rejected one or more unavailable domains. Previous selections will be excluded from the replacement quote.'}}];
if(!$json.order_id)throw new Error($json.error?.message||'No order ID returned');
const ids=[...c.previousIds,$json.order_id],done=ids.length>=c.totalBatches;
return [{json:{id:c.requestId,'Batch Order IDs':ids.join('\n'),'CheapInboxes Order ID':ids[0],'Completed Batches':ids.length,Status:done?'Provisioning':'Purchasing','Next Batch At':done?null:new Date(Date.now()+c.delay*60000).toISOString(),'Automation Error':''}}];

const response=$input.first().json;
if(!response.order_id)return [];
const request=response._purchaseContext?.request;
const requestedDomains=response._purchaseContext?.requestedDomains||[];
if(!request)throw Error('Saved purchase context missing; do not repurchase');
const workspaceLink=Array.isArray(request['Client / Workspace'])?request['Client / Workspace'][0]:request['Client / Workspace'];
const workspaceId=workspaceLink?.id||workspaceLink;
if(!workspaceId)throw new Error('Purchased order has no linked Client / Workspace');
const password=String(request['Mailbox Password']||'');
  if(!password)throw new Error('Purchased order is missing Mailbox Password');
const provider=String(request['Inbox Provider']?.name||request['Inbox Provider']||'Google');
const returnedDomains=Array.isArray(response.domains)?response.domains:[];
return returnedDomains.map((domainResult,index)=>{const requested=requestedDomains.find(x=>x.domain===domainResult.domain)||requestedDomains[index]||{};const mailboxes=(Array.isArray(response.mailboxes)?response.mailboxes:[]).filter(m=>String(m.full_email||'').toLowerCase().endsWith('@'+String(domainResult.domain).toLowerCase()));return {json:{workspaceId,password,provider,orderId:response.order_id,totalCharged:Number(response.total_charged_cents||0)/100,monthlyCost:Number(request['Monthly Inbox Cost']||0),promo:String(request['Promo Code']||''),domain:String(domainResult.domain),cheapInboxesDomainId:String(domainResult.id||''),mailboxCount:mailboxes.length||Number(requested.mailboxes?.accounts?.length||2),mailboxes}}});

const sources=$('Prepare Purchased Inventory').all(0,$runIndex).map(i=>i.json);
const records=$input.all();if(records.length!==sources.length)throw Error('Domain inventory incomplete; next purchase blocked');
return records.flatMap(item=>{const record=item.json;const source=sources.find(s=>s.domain===record.fields?.Domain);if(!record.id||!source)throw Error('Domain inventory identity mismatch');return source.mailboxes.map(m=>{if(!m.full_email)throw Error('Purchased mailbox missing email');return {json:{email:String(m.full_email),workspaceId:source.workspaceId,domainRecordId:record.id,password:source.password,loginUrl:source.provider.toLowerCase().includes('micro')?'https://outlook.office.com/mail/':'https://mail.google.com/'}};});});

const state = JSON.parse(JSON.stringify($json));
const needed = Math.max(0,state.count-state.domains.length);
const size = Math.min(20, Math.max(4, needed*2));
const batch = state.pendingKeywords.splice(0,size);
if(!batch.length) throw new Error('No remaining domain suggestions to check');
state.searchRound += 1;
return batch.map(keyword=>({json:{keyword,tlds:state.tlds,state}}));

const context=$('Prepare Quote Request').first().json;
const response=$json,body=response.body??response,status=Number(response.statusCode||200);
if(status===429||body.error?.code==='RATE_LIMIT_EXCEEDED') {
 return [{json:{...context,quoteReady:false,retryQuote:$runIndex<3,reviewMessage:'All requested domains were found, but the quote provider is still rate-limiting requests after automatic retries. Domains are saved; generate again later to refresh the quote.'}}];
}
if(status>=400||body.error||!body.quote?.totals)throw new Error(body.error?.message||'Invalid quote response');
return [{json:{context,quote:body.quote,quoteReady:true,retryQuote:false}}];

const response=$('PLACE ONE BATCH - CHARGES CARD').all(0,$runIndex)[0]?.json;
const batch=$('Build Next Batch').all(0,$runIndex)[0]?.json;
if(!response?.order_id)return [];
if(!batch?.requestSnapshot||$input.first().json.id!==batch.requestId)throw Error('Saved order context mismatch; stop before next purchase');
if(!Array.isArray(response.domains)||!response.domains.length||!Array.isArray(response.mailboxes)||!response.mailboxes.length)throw Error('Purchased inventory absent; reconcile existing order before continuing');
return [{json:{...response,_purchaseContext:{request:batch.requestSnapshot,requestedDomains:batch.checkoutBody.domains}}}];

const saved=$('Save Batch').all(0,$runIndex)[0]?.json;
const expected=$('Prepare Email Account Inventory').all(0,$runIndex).map(i=>i.json.email.toLowerCase());
const actual=$('Create Email Account Inventory').all(0,$runIndex).map(i=>{if(!i.json.id)throw Error('Mailbox save failed');return String(i.json.fields?.['Email Account']||'').toLowerCase();});
if(!saved?.id||!expected.length||actual.length!==expected.length||new Set(actual).size!==actual.length||expected.some(e=>!actual.includes(e)))throw Error('Mailbox inventory incomplete; next purchase blocked');
return [{json:saved}];
